var sortArr = function(arr, ind) {
    for (var i = 0; i < arr.length - 1; i++) {
        for (var j = i + 1; j < arr.length; j++) {
            if (arr[j][ind] <= arr[i][ind]) {
                var temp = arr[j];
                arr[j] = arr[i];
                arr[i] = temp;
                if (arr[j][0] === arr[i][0]) {
                    arr.splice(i, 1);
                }
            }
        }
    }
};
