    /** Player **/
    //{
    function cuteEyes(x,y,s,r,fade){
        pushMatrix();
            translate(x,y);
            scale(s);
            rotate(r);
            
            
            fill(0,0,0);
            noStroke();
            ellipse(0,0,100,100);
    
            fill(255, 255, 255);
            ellipse(-17,-11,50,50);
            ellipse(26,-15,15,15);
            ellipse(-13,32,15,15);
             rotate(-r);       
            rotate(+0);
            fill(255, 232, 229, fade);
            ellipse(-6,57,101,29);
            
        popMatrix();
        
    
    }
    function Player(x,y){
        this.x = x;
        this.y = y;
        this.h = 50;
        this.w = 40;
        
    
        
        this.colw = 40;
        this.colx = 0;
        
        //Current positions
        this.quads = [0,0,this.w,0,this.w,this.h,0,this.h,this.w-8,18,7,18,255,0];
        this.position = "stop";
        this.pospd = 0.07;
        
        //The speeds
        this.maxSpd = 1000;
        this.acc = 0.3;
        this.speed = 0;
        this.decel = 0.9;
        
        //gravity
        this.grav = 0.4;
        this.maxfall = 20;
        this.fallspd = 0;
        this.ajump = false;
        this.landTimer = 0;
         
        this.timeout = 0;//timing to switch back to the stop position 
        this.health = 100; //Health
                    
        //Order is left quad,right quad, bottom left, bottom right, eyes,eyes2,eyescutefade, mouth
        this.jumpA = [0,-3,this.w-15,-3,this.w+-8,this.h,-9,this.h,this.w-15,30,0,30,0,-7];
        this.moveLA = [-24,-5,this.w-32,-5,this.w+-1,this.h,1,this.h,-10,6,-10,6,0,-20];
        this.moveRA = [24,-5,this.w+7,-5,this.w+-1,this.h,1,this.h,this.w-3,6,this.w-3,6,0,15];
        this.fallA = [-2,-9,this.w+2,-9,this.w+-5,this.h,5,this.h,this.w-8,0,8,0,255,0];
        this.land = [0,20,this.w,25,this.w+20,this.h,-20,this.h,this.w-5,32,3,31,255,0];
        this.stop = [0,0,this.w,0,this.w,this.h,0,this.h,this.w-8,18,7,18,255,0];
        this.currentA = [0,0,this.w,0,this.w,this.h,0,this.h,0,0,0,0];
    }
    Player.prototype.pos_trans = function(){
        
        //Switching the "Going to be" position
        switch(this.position){
            case "left":
                
                for(var i = 0;i<14;i++){
                    this.currentA[i] =this.moveLA[i];
                }     
                this.pospd = 0.07;
            break;
            
            case "right":
                
                for(var i = 0;i<14;i++){
                    this.currentA[i] =this.moveRA[i];
                }          
                this.pospd = 0.07;
            break;
            
            case "stop":
                
                for(var i = 0;i<14;i++){
                    this.currentA[i] =this.stop[i];
                }          
                this.pospd = 0.07;
            break;        
            case "land":
                
                for(var i = 0;i<14;i++){
                    this.currentA[i] =this.land[i];
                }          
                this.pospd = this.landTimer/5;
            break;         
            case "fall":
                this.pospd = 0.1;
                for(var i = 0;i<14;i++){
                    this.currentA[i] =this.fallA[i];
                }          
                
            break;   
            case "jump":
                this.pospd = 0.07;
                for(var i = 0;i<14;i++){
                    this.currentA[i] =this.jumpA[i];
                }          
                
            break;  
        }
    };
    Player.prototype.update = function(){
       
        //Updating the figure of the cube
    
        this.timeout*=0.3;    
        if(this.timeout<=0.1&&this.ajump === true&&this.landTimer<0.2){
            this.position = "stop";
        }
        
         if(this.ajump === true&&this.landTimer>0.1&&this.fallspd<0.5){
            this.landTimer*=0.95;
            this.position = "land";
        }
        
        this.landTimer = constrain(this.landTimer,0.1,1.5);
        
        fill(255,0,0);
    //    text(this.fallspd,10,10);
      //  text(this.landTimer,100,10);
    };
    Player.prototype.moveX = function(){
        //--------------- X AXIS -----------------//
        
        //Moving the x axis with the speed
        this.x += this.speed;
        
        //Moving left and right
        if(keys[65] || keys[LEFT]){
            this.position = "left";
            this.timeout = 1;
            if (this.speed > -5){
                this.speed -= this.acc;
            }
        } 
        
        else if(keys[68] || keys[RIGHT]){
            this.position = "right";
            this.timeout = 1;
            if (this.speed < 5){
                this.speed += this.acc;
            }
        }
        else {
            this.speed *= this.decel;
        }    
    };
    Player.prototype.moveY = function(){
       //-----------Y AXIS----------//
        
        this.y += this.fallspd; //making the player fall
        
        this.fallspd +=this.grav; //applying world gravity
        
       this.fallspd = constrain(this.fallspd,-this.maxfall,this.maxfall);
        
        if(this.fallspd>1){
                this.position = "fall";
                this.landTimer+=0.05;
        }   
    
        
        if(keys[87] && this.ajump || keys[UP] && this.ajump){
            this.position = "jump";
            this.fallspd = -this.maxfall/1.6;
            this.ajump = false;
        }    
    };
    Player.prototype.draw = function(){
        this.update();
        this.pos_trans();
        
        var q = this.quads;
        
        //Drawing the looks 
        pushMatrix();
            translate(this.x-this.quads[0]/2,this.y);
            fill(0, 229, 245);        
            noStroke();
            quad(q[0],q[1],q[2],q[3],q[4],q[5],q[6],q[7]);
            
            cuteEyes(q[8],q[9],0.11,0,q[12]);
            cuteEyes(q[10],q[11],0.11,90,q[12]);
    
            fill(0,0,0);
            arc(20+q[13],this.h/2,9,10,0,180);  
    
    
            fill(255, 255, 255,100);
         //   rect(this.quads[0],q[1],this.quads[2]-this.quads[0],this.h-q[1]);
            
            fill(0,0,0);
         //   text(this.colx,0,0);
          //  text(this.x,0,20);
          //  text(this.quads[0],0,40);
        //    this.fallspd+=this.grav;
        popMatrix();
        
        //Collisions modified
        this.colw = this.quads[2]-this.quads[0];
        this.colx = this.x+this.quads[0];
        
        //Lerping the players body to the position specified
        for(var i = 0;i<14;i++){
            this.quads[i] =lerp(this.quads[i],this.currentA[i],this.pospd);
        }
      
    };
    var player;
    //}
    
    /** Block **/
    //{
        var Block = function(x, y, w, h, t){
            this.x = x; //X position
            this.y = y; //Y position
            this.w = w; //Width
            this.h = h; //Height
            this.t = t; //Type
            curLevel > 19  && curLevel < 25? this.color = color(117, 113, 108) : this.color = color(150, 110, 140);
        };
        Block.prototype.draw = function() {
            switch (this.t){
                case 0:
                    fill(this.color);
                    stroke(this.color);
                    strokeWeight(1);
                    rect(this.x, this.y, this.w, this.h);
                    image(texture,this.x,this.y);

                    
                break;
                case 1:
                    fill(209, 244, 255);
                    stroke(209, 244, 255);
                    strokeWeight(1);
                    rect(this.x, this.y, this.w, this.h);
                    fill(229, 249, 255);
                    noStroke();
                    quad(this.x + 20, this.y, this.x + 10, this.y + this.h, this.x + 30, this.y + this.h, this.x + 40, this.y);
                    noStroke();
                break;
            }
        };
        Block.prototype.collideX = function(obj1){
            switch (this.t) {
                case 0:
                    obj1.rightC = false;
                    obj1.leftC = false;
                    if (col(this, obj1)){
                        if (obj1.x < this.x) {
                            obj1.x = this.x - obj1.w;
                            obj1.rightC = true;
                        } 
                        else if (obj1.x>this.x){
                            obj1.x = this.x + this.w;
                            obj1.leftC = true;
                        }
                    }
                break;
                case 1:
                    if (col(this, obj1)){
                        
                        if (obj1.x < this.x) {
                            obj1.x = this.x - obj1.w;
                        } 
                        else if (obj1.x>this.x){
                            obj1.x = this.x + this.w;
                        }
                        
                    }
            }
        };
        Block.prototype.collideY = function(obj1){
            switch (this.t){
                case 0:
                    if (col(this, obj1)) {
                        
                        if (obj1.y < this.y) {
                            obj1.ajump = true;
                            obj1.y = this.y - obj1.h;
                            obj1.fallspd = 0;
                        } 
                        else if (obj1.y > this.y){
                            obj1.y = this.y + this.h;
                            obj1.ajump = false;
                            obj1.fallspd *= -0.5;
                        }
                    }
                break;
                case 1:
                    if (col(this, obj1)) {
                        obj1.speed *= 1.03;
                        if (obj1.y < this.y) {
                            obj1.ajump = true;
                            obj1.y = this.y - obj1.h;
                            obj1.fallspd = 0;
                        } 
                        else if (obj1.y > this.y){
                            obj1.y = this.y + this.h;
                            obj1.ajump = false;
                            obj1.fallspd *= -0.5;
                        }
                    }
                break;
            }
        };
    //}
    
    /** Obstacle **/
    //{
        var Obs = function(x, y, type){
            this.x = x;
            this.y = y;
            this.w = 50;
            this.h = 50;
            this.yetiX = x;
            this.yetiY = y;
            this.signY = -600;
            this.t = type;
        };
        Obs.prototype.draw = function(){
            switch (this.t){
                case 0:
                    noStroke();
                    fill(150, 150, 150);
                    triangle(this.x+25/2, this.y, this.x, this.y + 50, this.x + 25, this.y + 50);
                    triangle(this.x + 25, this.y + 50, this.x + 25+25/2, this.y, this.x + 50, this.y + 50);
                break;
                case 1:
                    stroke(19, 0, 128);
                    noFill();
                    strokeWeight(5);
                    ellipse(this.x + this.w/2, this.y + this.h/2 - 10 + sin(frameCount*2)*5, 40, 40);
                    stroke(0, 102, 133);
                    ellipse(this.x + this.w/2, this.y + this.h/2 - 10 + sin(frameCount*2)*5, sin(frameCount*4)*20, 20);
                    ellipse(this.x + this.w/2, this.y + this.h/2 - 10 + sin(frameCount*2)*5, 20, sin(frameCount*3)*20);
                    ellipse(this.x + this.w/2, this.y + this.h/2 - 10 + sin(frameCount*2)*5, sin(frameCount*3.5)*20, sin(frameCount*3.5)*20);
                    ellipse(this.x + this.w/2, this.y + this.h/2 - 10 + sin(frameCount*2)*5, 20, 20);
                    fill(0, 100);
                    noStroke();
                    ellipse(this.x + this.w/2, this.y + this.h, -sin(frameCount*2)*5 + 30, 5);
                break;
                case 2:
                    image(sign, this.x, this.y);
                break;
                case 3:
                    imageMode(CENTER);
                    pushMatrix();
                    translate(this.x + 25, this.y + 25);
                    rotate(frameCount*3);
                    image(T1, 0, 0);
                    popMatrix();
                    imageMode(CORNER);
                break;
                case 4:
                    imageMode(CENTER);
                    pushMatrix();
                    translate(this.x + 25, this.y + 25);
                    rotate(frameCount*3);
                    image(T2, 0, 0);
                    popMatrix();
                    imageMode(CORNER);
                break;
                case 5:
                    image(Trampoline, this.x, this.y);
                break;
                case 6:
                    image(yeti, this.x, this.y, 50, 52);
                break;
                case 7:
                     fill(0);
                     rect(this.x, this.y, 50, 50);
                break;
                    
            }
        };
    //}
    
    /** Smort Yeti **/
    //{
        var Yeti = function(x, y){
            //Coordinates
            this.x = x;
            this.y = y;
            
            //Dimensions
            this.w = 50;
            this.h = 50;
            
            //Move
            this.speed = 0;
            this.fallspd = 0;
            this.grav = 0.4;
            this.ajump = false;
            this.health = 100;
        };
        Yeti.prototype.draw = function() {
            image(smortyeti, this.x, this.y, 53, 53);
        };
        Yeti.prototype.moveX = function(obj){
            if (obj.x < this.x){
                this.speed = -2;
            }
            else if (obj.x > this.x){
                this.speed = 2;
            }
            else {
                this.speed *= 0.9;
            }
            if (col(this, obj)){
                obj.health--;
            }
            this.x += this.speed;
        };
        Yeti.prototype.moveY = function(obj){
            if (player.y < this.y && this.ajump){
                this.fallspd = -8;
                this.ajump = false;
                this.grav = 0.4;
            }
            this.y += this.fallspd;
            this.fallspd += this.grav;
        };
        var yetis = [];
    //}
    
