        var blocks = [];
        var block2s = [];
        var createLevel = function(){
            blocks[curLevel] = [];
            block2s[curLevel] = [];
            yetis[curLevel] = [];
            for (var i = 0;i<maps[curLevel].map.length;i++){
                for (var y = 0;y<maps[curLevel].map[i].length;y++){
                    var X = y*50;
                    var Y = i*50;
                    switch(maps[curLevel].map[i][y]){
                        case "B":
                            blocks[curLevel].push(new Block(X, Y, 50, 50, 0));
                        break;
                        case "@":
                            player = new Player(X,Y);
                        break;
                        case "^":
                            block2s[curLevel].push(new Obs(X, Y, 0));
                        break;
                        case "P":
                            block2s[curLevel].push(new Obs(X, Y, 1));
                        break;
                        case "S":
                            block2s[curLevel].push(new Obs(X, Y, 2));
                        break;
                        case "T":
                            block2s[curLevel].push(new Obs(X, Y, 3));
                        break;
                        case "&":
                            block2s[curLevel].push(new Obs(X, Y, 4));
                            maps[curLevel].teleportPlace = [X, Y];
                        break;
                        case "I":
                            blocks[curLevel].push(new Block(X, Y, 50, 50, 1));
                        break;
                        case "3":
                            block2s[curLevel].push(new Obs(X, Y, 5));
                        break;
                        case "Y":
                            block2s[curLevel].push(new Obs(X, Y, 6));
                        break;
                        case "U":
                            yetis[curLevel].push(new Yeti(X, Y));
                        break;
                        case "A":
                            block2s[curLevel].push(new Obs(X, Y, 7));
                        break;
                    }
                }
            }
        };
        Obs.prototype.collide = function(obj){
            if (this.t === 6){
                this.x = this.yetiX + sin(frameCount)*70;
            }
            if (this.t === 7){
                this.x = this.yetiX + sin(frameCount)*70;
                this.y = this.yetiY + sin(frameCount*4)*70;
            }
            if (col(this, obj)){
                switch (this.t){
                    case 0:
                        obj.health-=3;
                        obj.fallspd = -10;
                        obj.ajump = false;
                    break;
                    case 1:
                        die(createLevel, true);
                    break;
                    case 2:
                        this.signY = lerp(this.signY, 0, 0.1);
                    break;
                    case 3:
                        obj.x = maps[curLevel].teleportPlace[0];
                        obj.y = maps[curLevel].teleportPlace[1];
                    break;
                    case 5:
                        obj.fallspd = -20;
                    break;
                    case 6:
                        obj.health--;
                    case 7:
                        obj.health--;
                }
            }
            else {
                this.signY = lerp(this.signY, -600, 0.1);
            }
        };
        Obs.prototype.drawSign = function(){
            fill(0, 150);
            rect(0 - this.signY/2, this.signY, this.signY+600, this.signY+600);
            fill(255);
            textFont(fb, 30);
            pushMatrix();
            translate(300, this.signY + 300);
            scale(this.signY/600 + 1);
            text(maps[curLevel].message, 0, 0);
            popMatrix();
        };
    //}
    
    /** Snow **/
    //{
        var snowFall = (function(){
            var snow = [];
            var timerYay = 0;
            return function(){
                if (frameCount % 30 === 10){
                    snow.push({
                        x: random(0, 600),
                        y: -400,
                        xSpeed: random(-6, 6)
                    });
                }
                for (var i = 0;i<snow.length;i++){
                    fill(245, 240, 255);
                    noStroke();
                    ellipse(snow[i].x,snow[i].y, 7, 7);
                    snow[i].x-=snow[i].xSpeed;
                    snow[i].y+=10;
                    if (snow[i].x<-100){
                        if (snow.length<100){
                            snow[i].x = random(-100,500);
                            snow[i].y = -200;
                            snow[i].xSpeed = random(0.1,10);
                        }
                        else {
                            snow.splice(i, 1);
                        }
                    }
                    if (snow.length>200){
                        snow.splice(i, 200);
                    }
                }
        
            };
        })();
    //}
