    draw = function(){
        try {
            switch (scene) {
                case "logo":
                    logo();
                break;
                case "menu":
                    menu();
                break;
                case "game":
                    game();
                break;
                case "win":
                    win();
                break;
                case "win2":
                    win2();
                break;
                case "how":
                    how();
                break;
                case "lead":
                    lead();
            }
        }
        catch (e){
            println(e);
        }
        clicked[mouseButton] = false;
        typed[keyCode] = false;
    };
    mouseClicked = function(){
        clicked[mouseButton] = true;
    };
    keyPressed = function(){
        keys[keyCode] = true;
    };
    keyReleased = function(){
        keys[keyCode] = false;
        typed[keyCode] = true;
    };
